package wgmodern;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;

@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class WallMirrorServerTests {
    static BlockPos place(GameTestHelper h,String name,Direction direction){var player=PrimordialServerTests.player(h,name);player.setYRot(direction.toYRot());var pos=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlockAndUpdate(pos.below(),Blocks.STONE.defaultBlockState());player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(WallMirror.ITEM.get()));var hit=new BlockHitResult(Vec3.atCenterOf(pos.below()),Direction.UP,pos.below(),false);var result=((WallMirror.MirrorItem)WallMirror.ITEM.get()).place(new BlockPlaceContext(player,InteractionHand.MAIN_HAND,player.getMainHandItem(),hit));h.assertTrue(result.consumesAction(),"Mirror item places paired blocks");return pos;}
    @GameTest(template="empty") public static void wallMirrorPlacesBothHalvesAndRejectsOccupiedUpperSpace(GameTestHelper h){var pos=place(h,"WGMirrorPlacement",Direction.SOUTH);var l=h.getLevel();h.assertTrue(l.getBlockState(pos).getValue(WallMirror.FACING)==Direction.NORTH&&l.getBlockState(pos.above()).getValue(WallMirror.HALF)==DoubleBlockHalf.UPPER,"Old player-yaw facing and dummy upper half preserved");var shape=l.getBlockState(pos).getShape(l,pos).bounds();h.assertTrue(shape.minZ==.9375&&shape.maxZ==1,"One-pixel collision slab sits at back of north-facing block");var p=PrimordialServerTests.player(h,"WGMirrorBlocked");var blocked=pos.east(2);l.setBlockAndUpdate(blocked.below(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(blocked.above(),Blocks.STONE.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(WallMirror.ITEM.get()));var hit=new BlockHitResult(Vec3.atCenterOf(blocked.below()),Direction.UP,blocked.below(),false);var result=((WallMirror.MirrorItem)WallMirror.ITEM.get()).place(new BlockPlaceContext(p,InteractionHand.MAIN_HAND,p.getMainHandItem(),hit));h.assertTrue(!result.consumesAction()&&l.isEmptyBlock(blocked),"Cannot overwrite occupied upper space");pass(h);}
    @GameTest(template="empty") public static void wallMirrorUpperClickUsesBaseAnimationAndDoesNotAddTeleportation(GameTestHelper h){var pos=place(h,"WGMirrorAnimation",Direction.SOUTH);var l=h.getLevel();var player=PrimordialServerTests.player(h,"WGMirrorClick");var before=player.position();var upper=l.getBlockState(pos.above());var tile=(WallMirror.Tile)l.getBlockEntity(pos);upper.use(l,player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos.above()),Direction.NORTH,pos.above(),false));h.assertTrue(tile.activating,"Upper clicks target lower tile");for(int i=0;i<32;i++)tile.tick();h.assertTrue(tile.active&&!tile.activating,"Activation completes after 32 ticks");h.assertTrue(player.position().equals(before),"Original mirror never teleports");player.setShiftKeyDown(true);upper.use(l,player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos.above()),Direction.NORTH,pos.above(),false));h.assertTrue(!tile.deactivating,"Sneaking does not toggle");player.setShiftKeyDown(false);var tag=tile.saveWithoutMetadata();var loaded=new WallMirror.Tile(pos,l.getBlockState(pos));loaded.load(tag);h.assertTrue(loaded.active&&!loaded.activating&&!loaded.deactivating,"Saved active state persists, transient animation does not");tile.toggle();for(int i=0;i<24;i++)tile.tick();h.assertTrue(!tile.active&&!tile.deactivating&&tile.activationAnimation==0,"Closing uses 31-to-16 single steps then double steps");pass(h);}
    @GameTest(template="empty") public static void wallMirrorBreakingUpperRemovesBaseWithoutDuplicatingDrops(GameTestHelper h){var pos=place(h,"WGMirrorDrop",Direction.SOUTH);var l=h.getLevel();l.destroyBlock(pos.above(),true);h.assertTrue(l.isEmptyBlock(pos)&&l.isEmptyBlock(pos.above()),"Either half removes the pair");h.assertTrue(l.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(2),e->e.getItem().is(WallMirror.ITEM.get())).isEmpty(),"Original dummy upper drops nothing; no partner duplication");pos=place(h,"WGMirrorDropAgain",Direction.EAST);var tile=(WallMirror.Tile)l.getBlockEntity(pos);h.assertTrue(tile.reflectedArea().contains(pos.getX()-7,pos.getY()+1,pos.getZ())&&!tile.reflectedArea().contains(pos.getX()+2,pos.getY()+1,pos.getZ()),"West-facing mirror searches original forward eight-block volume");l.destroyBlock(pos,true);int dropped=l.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(2),e->e.getItem().is(WallMirror.ITEM.get())).stream().mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(dropped==1,"Lower half drops one item");h.assertTrue(tc4revival.research.ResearchCatalogs.catalog().find("witchinggadgets:WALLMIRROR").isEmpty(),"Research remains unpublished as in original");if(tc4revival.config.TCConfig.SERVER.allowMirrors.get())h.assertTrue(l.getRecipeManager().byKey(new ResourceLocation("witchinggadgets","wall_mirror")).isPresent(),"Original hidden-research-gated infusion is registered");pass(h);}
    private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
